void RegisterBJLLHHFDAEMHooks() {
    jk::RegisterHookTable(jk::bjllhhfdaem_detail::kHooks, jk::bjllhhfdaem_detail::kHookCount);
}

int InstallBJLLHHFDAEMHooks(uint64_t base) {
    // 正常路径是 dllmain 先 RegisterAll（日志/过滤/签名表都要用）再 Install；
    // 万一没登记，这里兜底登记一次（只在调用顺序不对时发生，会重置过滤表）。
    if (!jk::HasHookTable()) RegisterBJLLHHFDAEMHooks();
    return jk::InstallAllHooks(base);
}

int BJLLHHFDAEMHookCount() { return jk::bjllhhfdaem_detail::kHookCount; }

void RemoveBJLLHHFDAEMHooks() { jk::RemoveAllHooks(); }
